{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")

    if "nodes" not in case or "core_distance" not in case or "distances" not in case:
        raise ValueError("missing required input field")

    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list):
        raise ValueError("nodes must be a list")
    if not isinstance(core_distance, dict):
        raise ValueError("core_distance must be an object")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    seen = set()
    for node in nodes:
        if not isinstance(node, str):
            raise ValueError("node identifiers must be strings")
        if node in seen:
            raise ValueError("duplicate node identifier")
        seen.add(node)

    node_set = set(nodes)
    for node in nodes:
        if node not in core_distance:
            raise ValueError("missing core distance")
        value = core_distance[node]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("core distances must be numeric")

    edges = []
    seen_pairs = set()
    for row in distances:
        if not isinstance(row, (list, tuple)) or len(row) != 3:
            raise ValueError("distance entries must be triples")
        left, right, distance = row
        if not isinstance(left, str) or not isinstance(right, str):
            raise ValueError("distance endpoints must be strings")
        if left not in node_set or right not in node_set:
            raise ValueError("distance endpoint is not in nodes")
        if left == right:
            raise ValueError("self distances are not valid MST edges")
        if isinstance(distance, bool) or not isinstance(distance, (int, float)):
            raise ValueError("distances must be numeric")

        a, b = (left, right) if left <= right else (right, left)
        pair = (a, b)
        if pair in seen_pairs:
            raise ValueError("duplicate undirected distance entry")
        seen_pairs.add(pair)

        weight = max(float(core_distance[a]), float(core_distance[b]), float(distance))
        edges.append((weight, a, b))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        root_left = find(left)
        root_right = find(right)
        if root_left == root_right:
            return False
        if rank[root_left] < rank[root_right]:
            parent[root_left] = root_right
        elif rank[root_left] > rank[root_right]:
            parent[root_right] = root_left
        else:
            parent[root_right] = root_left
            rank[root_left] += 1
        return True

    selected = []
    total = 0.0
    for weight, left, right in sorted(edges, key=lambda item: (item[0], item[1], item[2])):
        if union(left, right):
            selected.append([left, right, weight])
            total += weight
            if len(selected) == max(0, len(nodes) - 1):
                break

    if len(selected) != max(0, len(nodes) - 1):
        raise ValueError("input graph is disconnected")

    return {"mst_edges": selected, "total_weight": total}
